import React, { useState } from 'react';

const ReportarMascotaPage = () => {
  const [nombre, setNombre] = useState('');
  const [ubicacion, setUbicacion] = useState({ lat: '', lng: '' });
  const [foto, setFoto] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    const reportData = {
      name: nombre,
      location: JSON.stringify(ubicacion),
      // Agregar otros campos como foto si es necesario
    };

    // Enviar datos al backend
    try {
      const response = await fetch('/api/reportar-mascota', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(reportData),
      });

      if (response.ok) {
        // Manejar respuesta exitosa
        console.log('Mascota reportada con éxito');
      } else {
        // Manejar error
        console.error('Error al reportar la mascota');
      }
    } catch (error) {
      console.error('Error de red:', error);
    }
  };

  return (
    <div style={{ padding: '20px' }}>
      <h1>Reportar Mascota</h1>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          placeholder="Nombre de la mascota"
          value={nombre}
          onChange={(e) => setNombre(e.target.value)}
          required
        />
        {/* Aquí podrías integrar un componente de mapa para seleccionar la ubicación */}
        <input
          type="text"
          placeholder="Ubicación (lat, lng)"
          value={`${ubicacion.lat}, ${ubicacion.lng}`}
          onChange={(e) => {
            const [lat, lng] = e.target.value.split(',').map(Number);
            setUbicacion({ lat, lng });
          }}
          required
        />
        <button type="submit">Reportar mascota</button>
      </form>
    </div>
  );
};

export default ReportarMascotaPage;
